"use client";

import { useState } from "react";

/** The number of lattice points m + nτ, τ = a + bi, with |m + nτ| ≤ R. */
export function latticeCount(a: number, b: number, R: number) {
  let c = 0;
  const nMax = Math.ceil(R / b) + 1;
  for (let n = -nMax; n <= nMax; n++) {
    const mMax = Math.ceil(R + Math.abs(n * a)) + 1;
    for (let m = -mMax; m <= mMax; m++) {
      const x = m + n * a, y = n * b;
      if (x * x + y * y <= R * R + 1e-9) c++;
    }
  }
  return c;
}

/** The lattice generated by 1 and τ, its fundamental parallelogram, and a count of lattice points in a disc. */
export function PeriodLatticeViz() {
  const [a, setA] = useState(0.3);
  const [b, setB] = useState(1);
  const [R, setR] = useState(3);
  const S = 26, X0 = 270, Y0 = 135;
  const px = (x: number) => X0 + x * S, py = (y: number) => Y0 - y * S;
  const pts: [number, number, boolean][] = [];
  for (let n = -8; n <= 8; n++) for (let m = -16; m <= 16; m++) {
    const x = m + n * a, y = n * b;
    if (Math.abs(x) <= 9.8 && Math.abs(y) <= 4.9) pts.push([x, y, x * x + y * y <= R * R + 1e-9]);
  }
  const count = latticeCount(a, b, R);
  const fmt = (v: number) => v.toFixed(1).replace("-", "−");
  return (
    <figure className="viz">
      <div className="viz-controls">
        <label>Re τ = {fmt(a)} <input type="range" min={-0.5} max={0.5} step={0.1} value={a} onChange={(e) => setA(Number(e.target.value))} aria-label="real part of tau" /></label>
        <label>Im τ = {b.toFixed(1)} <input type="range" min={0.6} max={2} step={0.1} value={b} onChange={(e) => setB(Number(e.target.value))} aria-label="imaginary part of tau" /></label>
        <label>R = {R.toFixed(1)} <input type="range" min={1} max={4.5} step={0.5} value={R} onChange={(e) => setR(Number(e.target.value))} aria-label="radius" /></label>
      </div>
      <svg viewBox="0 0 540 270" role="img" aria-label="The period lattice generated by 1 and tau" style={{ width: "100%", display: "block", marginTop: 8 }}>
        <line x1={14} y1={Y0} x2={526} y2={Y0} style={{ stroke: "var(--grid-line)" }} />
        <line x1={X0} y1={6} x2={X0} y2={264} style={{ stroke: "var(--grid-line)" }} />
        <polygon points={`${px(0)},${py(0)} ${px(1)},${py(0)} ${px(1 + a)},${py(b)} ${px(a)},${py(b)}`} style={{ fill: "var(--accent-soft)", stroke: "var(--accent)", strokeWidth: 1.5 }} />
        <circle cx={X0} cy={Y0} r={R * S} style={{ fill: "none", stroke: "var(--success)", strokeWidth: 2, strokeDasharray: "5 3" }} />
        {pts.map(([x, y, inside], i) => (
          <circle key={i} cx={px(x)} cy={py(y)} r={inside ? 3.6 : 2.4} style={{ fill: inside ? "var(--success)" : "var(--text-faint)" }} />
        ))}
        <text x={px(1) + 4} y={py(0) + 14} style={{ fill: "var(--text)", fontSize: 11 }}>1</text>
        <text x={px(a) - 4} y={py(b) - 6} textAnchor="end" style={{ fill: "var(--text)", fontSize: 11 }}>τ</text>
      </svg>
      <p className="mono" style={{ fontSize: 13, fontWeight: 700 }}>
        Lattice points with |ω| ≤ {R.toFixed(1)}: {count}. Area of the parallelogram: {b.toFixed(1)}, so about πR² / {b.toFixed(1)} = {(Math.PI * R * R / b).toFixed(1)} are expected.
      </p>
      <figcaption className="viz-caption">
        The lattice Λ = ℤ + ℤτ is the set of periods of an elliptic function. The shaded parallelogram with corners 0, 1,
        1 + τ and τ is a fundamental domain: its translates by Λ tile the plane, and an elliptic function is known once it
        is known there. The number of periods in a disc grows like the area of the disc divided by the area of the
        parallelogram.
      </figcaption>
    </figure>
  );
}
